{"success": true, "data": {"stdout": """"Aggregate N candidates using selection strategies and evaluate.

Strategies: self_consistency (IoU voting), oracle (best F1), random.
Input: inference result files + gold labels
Output: final_results.json with F1 per (N, strategy)
"""
import argparse
import json
import os
import sys
import random
import glob
from collections import defaultdict

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from evaluate import compute_f1, compute_micro_f1


def locate_spans(doc_text, entities):
    """Find character offsets for entities in source text (context-aware).

    For duplicate entity texts, assigns spans by matching the k-th occurrence
    in the candidate list to the k-th occurrence in the document.
    """
    text_to_indices = defaultdict(list)
    for i, e in enumerate(entities):
        text = e.get("text", "")
        if text:
            text_to_indices[text].append(i)
        else:
            e["_start"] = None
            e["_end"] = None

    for text, indices in text_to_indices.items():
        positions = []
        start = 0
        while True:
            idx = doc_text.find(text, start)
            if idx < 0:
                break
            positions.append(idx)
            start = idx + 1

        for k, ent_idx in enumerate(indices):
            if k < len(positions):
                entities[ent_idx]["_start"] = positions[k]
                entities[ent_idx]["_end"] = positions[k] + len(text)
            else:
                entities[ent_idx]["_start"] = None
                entities[ent_idx]["_end"] = None


def span_iou(e1, e2):
    """Span IoU between two entities. Falls back to text match if offsets missing."""
    s1, e1_end = e1.get("_start"), e1.get("_end")
    s2, e2_end = e2.get("_start"), e2.get("_end")
    if s1 is not None and s2 is not None and e1_end is not None and e2_end is not None:
        overlap = max(0, min(e1_end, e2_end) - max(s1, s2))
        union = max(e1_end, e2_end) - min(s1, s2)
        return overlap / union if union > 0 else 0.0
    return 1.0 if e1.get("text", "") == e2.get("text", "") else 0.0


def entity_agreement(cand_i, cand_j, iou_threshold=0.5):
    """Agreement score between two candidate entity lists.
    F1-like: 2 * matched / (len_i + len_j). Match = IoU >= threshold AND same type.
    """
    if not cand_i and not cand_j:
        return 1.0
    if not cand_i or not cand_j:
        return 0.0

    matched_j = set()
    matches = 0
    for ei in cand_i:
        for jdx, ej in enumerate(cand_j):
            if jdx in matched_j:
                continue
            if ei.get("type", "") != ej.get("type", ""):
                continue
            if span_iou(ei, ej) >= iou_threshold:
                matches += 1
                matched_j.add(jdx)
                break

    return 2 * matches / (len(cand_i) + len(cand_j))


def select_self_consistency(candidates, doc_text):
    """Select candidate with highest average agreement with others."""
    n = len(candidates)
    if n <= 1:
        return 0

    # Locate spans for IoU computation
    for cand in candidates:
        locate_spans(doc_text, cand)

    scores = []
    for i in range(n):
        s = sum(entity_agreement(candidates[i], candidates[j]) for j in range(n) if j != i) / (n - 1)
        scores.append(s)

    return max(range(n), key=lambda i: scores[i])


def select_oracle(candidates, gold_entities):
    """Select candidate with highest F1 vs gold."""
    best_idx, best_f1 = 0, -1.0
    for i, cand in enumerate(candidates):
        _, _, f1 = compute_f1(cand, gold_entities)
        if f1 > best_f1:
            best_f1 = f1
            best_idx = i
    return best_idx


def select_random(candidates, rng):
    return rng.randint(0, len(candidates) - 1)


def load_results(results_dir, n_candidates, seed):
    """Load all shard results for given (n, seed). Returns {doc_id: {text, candidates}}."""
    pattern = os.path.join(results_dir, f"shard_*_n{n_candidates}_seed{seed}.jsonl")
    files = sorted(glob.glob(pattern))
    docs = {}
    for fpath in files:
        with open(fpath) as f:
            for line in f:
                if not line.strip():
                    continue
                doc = json.loads(line.strip())
                docs[doc["doc_id"]] = {"text": doc["text"], "candidates": doc["candidates"]}
    return docs


def load_gold(gold_file):
    gold = {}
    with open(gold_file) as f:
        for line in f:
            if not line.strip():
                continue
            doc = json.loads(line.strip())
            gold[doc["doc_id"]] = doc["entities"]
    return gold


def evaluate_config(doc_candidates, gold, strategy, rng=None):
    all_preds, all_golds = [], []
    for doc_id in sorted(doc_candidates.keys()):
        info = doc_candidates[doc_id]
        candidates = info["candidates"]
        gold_entities = gold.get(doc_id, [])

        if strategy == "self_consistency":
            idx = select_self_consistency(candidates, info["text"])
        elif strategy == "oracle":
            idx = select_oracle(candidates, gold_entities)
        elif strategy == "random":
            idx = select_random(candidates, rng)
        else:
            raise ValueError(f"Unknown strategy: {strategy}")

        selected = candidates[idx] if idx < len(candidates) else []
        all_preds.append(selected)
        all_golds.append(gold_entities)

    return compute_micro_f1(all_preds, all_golds)


def main():
    parser = argparse.ArgumentParser(description="Aggregate candidates and evaluate")
    parser.add_argument("--results_dir", required=True)
    parser.add_argument("--gold_file", required=True)
    parser.add_argument("--output_file", required=True)
    args = parser.parse_args()

    gold = load_gold(args.gold_file)
    all_results = {}

    # N=1: greedy, no selection
    n1_docs = load_results(args.results_dir, 1, 42)
    if n1_docs:
        preds, golds = [], []
        for doc_id in sorted(n1_docs.keys()):
            cands = n1_docs[doc_id]["candidates"]
            preds.append(cands[0] if cands else [])
            golds.append(gold.get(doc_id, []))
        m = compute_micro_f1(preds, golds)
        all_results["n1"] = {"greedy": {"f1": m["f1"], "precision": m["precision"], "recall": m["recall"], "per_type": m["per_type"]}}
        print(f"N=1 greedy: F1={m['f1']:.4f}")

    # N=4,8,16
    strategies = ["self_consistency", "oracle", "random"]
    for n in [4, 8, 16]:
        n_results = {}
        for strategy in strategies:
            seed_metrics = []
            for seed in [42, 123, 456]:
                doc_candidates = load_results(args.results_dir, n, seed)
                if not doc_candidates:
                    continue
                rng = random.Random(seed) if strategy == "random" else None
                m = evaluate_config(doc_candidates, gold, strategy, rng)
                seed_metrics.append({"seed": seed, "f1": m["f1"], "precision": m["precision"], "recall": m["recall"]})
                print(f"N={n} seed={seed} {strategy}: F1={m['f1']:.4f}")

            if seed_metrics:
                avg_f1 = sum(x["f1"] for x in seed_metrics) / len(seed_metrics)
                n_results[strategy] = {"mean_f1": avg_f1, "seeds": seed_metrics}
                print(f"  N={n} {strategy} mean: F1={avg_f1:.4f}")

        if n_results:
            all_results[f"n{n}"] = n_results

    os.makedirs(os.path.dirname(os.path.abspath(args.output_file)), exist_ok=True)
    with open(args.output_file, "w") as f:
        json.dump(all_results, f, indent=2)
    print(f"\nSaved: {args.output_file}")


if __name__ == "__main__":
    main()
